classpps <- read.csv("data/classpps.csv")

res_upswo <- cluster_upswo_ratio_est(
  data = classpps, 
  cname = "class", 
  csize = "clssize", 
  cpik = "clssize", # Assuming inclusion prob is proportional to class size
  yvar = "hours"
)

# Display the cluster-level summary
res_upswo$summary |> 
